urlset:
{{-- Static Core Pages --}}

    {{ rtrim($page->baseUrl, '/') }}/
    {{ date('Y-m-d') }}
    weekly
    1.0


    {{ rtrim($page->baseUrl, '/') }}/bpmn
    {{ date('Y-m-d') }}
    weekly
    0.9


    {{ rtrim($page->baseUrl, '/') }}/blog
    {{ $posts->first() ? date('Y-m-d', $posts->first()->date) : date('Y-m-d') }}
    weekly
