{{-- Documentation Pages --}}
@foreach ($bpmn_docs as $doc)
    @php
        $sourceFile = $doc->_meta->sourcePath ?? null;
        $lastmod = ($sourceFile && file_exists($sourceFile))
            ? date('Y-m-d', filemtime($sourceFile))
            : date('Y-m-d');
    @endphp

        {{ $doc->getUrl() }}
        {{ $lastmod }}
        monthly
        0.8

@endforeach

{{-- Blog Posts --}}
@foreach ($posts as $post)
    @php
        $lastmod = $post->updated
            ? date('Y-m-d', $post->updated)
            : date('Y-m-d', $post->date);
    @endphp

        {{ $post->getUrl() }}
        {{ $lastmod }}
        monthly
        0.7

@endforeach
